classDiagram
    class EventEmitter {
        -listeners: Map
        +on(event, fn) void
        +emit(event, data) void
    }
    class Observer {
        +update(data) void
    }
    class Strategy {
        +execute(data) any
    }
    class Context {
        -strategy: Strategy
        +setStrategy(s) void
        +run(data) any
    }
    class Command {
        +execute() void
        +undo() void
    }
    class Invoker {
        -history: Command[]
        +run(cmd) void
        +undoLast() void
    }
    Context --> Strategy : delegates
    Invoker --> Command : executes
    EventEmitter --> Observer : notifies

