// ── Observer (EventEmitter) ──────────────────────────────────────
class EventEmitter {
  constructor() { this._listeners = {}; }
  on(event, fn)   { (this._listeners[event] ??= []).push(fn); return this; }
  off(event, fn)  { this._listeners[event] = (this._listeners[event] ?? []).filter(f => f !== fn); }
  emit(event, data) { (this._listeners[event] ?? []).forEach(fn => fn(data)); }
}

const bus = new EventEmitter();
bus.on('order:placed', o => console.log(`Email: order ${o.id} confirmed`));
bus.on('order:placed', o => console.log(`Slack: new order ${o.id} from ${o.user}`));
bus.emit('order:placed', { id: 42, user: 'alice' });
// Email: order 42 confirmed
// Slack: new order 42 from alice

// ── Strategy ────────────────────────────────────────────────────
const shippingStrategies = {
  standard:  (weight) => weight * 1.5,
  express:   (weight) => weight * 4.0,
  overnight: (weight) => weight * 7.5,
};
function calculateShipping(weight, strategyName) {
  const strategy = shippingStrategies[strategyName];
  if (!strategy) throw new Error(`Unknown strategy: ${strategyName}`);
  return strategy(weight);
}
console.log(calculateShipping(10, 'express'));   // 40
console.log(calculateShipping(10, 'standard'));  // 15

// ── Command ─────────────────────────────────────────────────────
class TextEditor {
  constructor() { this.text = ''; }
  insert(str)   { this.text += str; }
  delete(n)     { this.text = this.text.slice(0, -n); }
}
function makeInsertCommand(editor, str) {
  return {
    execute: () => editor.insert(str),
    undo:    () => editor.delete(str.length),
  };
}

const editor   = new TextEditor();
const history  = [];
function run(cmd) { cmd.execute(); history.push(cmd); }
function undoLast() { history.pop()?.undo(); }

run(makeInsertCommand(editor, 'Hello'));
run(makeInsertCommand(editor, ', world'));
console.log(editor.text); // Hello, world
undoLast();
console.log(editor.text); // Hello

// ── State Pattern ───────────────────────────────────────────────
// Each state is an object; the context delegates to the current state.
const TrafficLight = {
  states: {
    red:    { color: 'red',    duration: 3000, next: () => TrafficLight.states.green  },
    green:  { color: 'green',  duration: 2500, next: () => TrafficLight.states.yellow },
    yellow: { color: 'yellow', duration: 500,  next: () => TrafficLight.states.red    },
  },
  current: null,
  init() {
    this.current = this.states.red;
    return this;
  },
  tick() {
    console.log(`Light is ${this.current.color}`);
    this.current = this.current.next(); // transition
  },
};

TrafficLight.init();
TrafficLight.tick(); // Light is red
TrafficLight.tick(); // Light is green
TrafficLight.tick(); // Light is yellow
TrafficLight.tick(); // Light is red (cycles)

// ── Pattern vs. anti-pattern ────────────────────────────────────
// Anti-pattern: giant switch in the context
function tick_bad(light) {
  if (light.state === 'red')    { light.state = 'green';  }
  else if (light.state === 'green')  { light.state = 'yellow'; }
  else if (light.state === 'yellow') { light.state = 'red';    }
  // Adding a new state requires editing this function
}

// State pattern: adding 'blinking' state touches only the states object
